python3 << 'PY'
import json, collections, re

def iter_paso2(path):
    in_paso2=False
    with open(path) as f:
        for i, line in enumerate(f, 1):
            line=line.strip()
            if not line: continue
            o=json.loads(line)
            tipo=o.get('tipo')
            if tipo=='paso_inicio' and o.get('orden')==2:
                in_paso2=True
                yield i,o
                continue
            if tipo=='paso_fin' and in_paso2:
                yield i,o
                return
            if in_paso2:
                yield i,o

def extract_tools(path):
    print(f"\n{'='*80}\n{path}\n{'='*80}")
    writes=[]
    edits=[]
    bash=[]
    other_tools=collections.Counter()
    tool_names=collections.Counter()
    write_like_bash=[]
    sample_assistant_content_types=collections.Counter()
    n_asst=0
    for i,o in iter_paso2(path):
        if o.get('tipo')!='evento_cli':
            continue
        p=o.get('payload') or {}
        tipo_cli=o.get('tipo_cli')
        # assistant tool uses
        msg=p.get('message') if isinstance(p, dict) else None
        if tipo_cli=='assistant' and isinstance(msg, dict):
            content=msg.get('content')
            if isinstance(content, list):
                for c in content:
                    if not isinstance(c, dict):
                        sample_assistant_content_types[type(c).__name__]+=1
                        continue
                    sample_assistant_content_types[c.get('type','?')]+=1
                    if c.get('type')=='tool_use':
                        name=c.get('name')
                        tool_names[name]+=1
                        inp=c.get('input') or {}
                        if name in ('Write','write'):
                            writes.append((i, inp.get('file_path') or inp.get('path'), list(inp.keys()), (inp.get('content') or '')[:80]))
                        elif name in ('Edit','NotebookEdit','edit'):
                            edits.append((i, name, inp.get('file_path') or inp.get('path'), inp.get('old_string','')[:40] if isinstance(inp.get('old_string'),str) else None))
                        elif name in ('Bash','bash'):
                            cmd=inp.get('command') or inp.get('cmd') or ''
                            bash.append((i, cmd[:300]))
                            if re.search(r'(>|>>|tee |cat >|patch |ApplyPatch)', cmd):
                                write_like_bash.append((i, cmd[:400]))
                        else:
                            other_tools[name]+=1
            elif content is not None:
                sample_assistant_content_types[f"nonlist:{type(content).__name__}"]+=1
                n_asst+=1
        elif tipo_cli=='user':
            # tool results might have file writes?
            pass
    print("assistant content types:", sample_assistant_content_types)
    print("tool names:", tool_names)
    print(f"\n--- WRITES ({len(writes)}) ---")
    for w in writes:
        print(w)
    print(f"\n--- EDITS ({len(edits)}) ---")
    for e in edits[:50]:
        print(e)
    if len(edits)>50:
        print(f"... {len(edits)-50} more")
    print(f"\n--- WRITE-LIKE BASH ({len(write_like_bash)}) ---")
    for b in write_like_bash:
        print(b)
    print(f"\n--- ALL BASH ({len(bash)}) ---")
    for b in bash:
        print(f"L{b[0]}: {b[1]}")
    print(f"\n--- OTHER TOOLS ---")
    print(other_tools)

for p in ["logs/backend.jsonl","logs/web.jsonl","logs/mobile.jsonl"]:
    extract_tools(p)
