1→/**
 * Función pura de alto nivel de la épica 06: `(seed, address_index)` ⇒ dirección de
 * depósito Ethereum, siguiendo el path BIP-44 estándar de Ethereum.
 *
 * Fuente normativa: BIP-32, BIP-44 (coin type 60 / SLIP-44), EIP-55.
 * Spec del proyecto: HU-06-02 RN-2 (path `m/44'/60'/0'/0/address_index`),
 * RN-4 (dirección + checksum EIP-55), RN-5 (determinismo / INV-8),
 * RN-6 (custodia: la clave privada no sale de aquí), RN-8 (salto de índice inválido)
 * y RN-9 (rango no-hardened del `address_index`); HU-06-03 RN-1 y RN-13.
10→ */
import { AppError, validationError } from '../../shared/errors.js';
import { publicKeyToAddress } from './address.js';
import { HARDENED_OFFSET, InvalidChildKeyError, derivePath, publicKeyXY } from './bip32.js';

/** Path base BIP-44 de Ethereum, sin el `address_index` (HU-06-02 RN-2). */
export const ETHEREUM_BASE_PATH = "m/44'/60'/0'/0";

/** Coin type de Ethereum según SLIP-44 (00-fundaciones/activos-y-par-de-trading §1). */
export const COIN_TYPE = 60;
20→
/** chainId de la red única del proyecto: Sepolia (HU-06-02 RN-7, INV-6). */
export const CHAIN_ID = 11_155_111;

/** Último índice del espacio **no-hardened** de BIP-32: 2³¹ − 1 (HU-06-02 RN-9). */
export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;

/** Resultado de una derivación. No incluye la clave privada (HU-06-02 RN-6). */
export interface DerivedAccount {
  readonly addressIndex: number;
30→  readonly address: string;
  readonly derivationPath: string;
  readonly publicKeyXY: Uint8Array;
}

/** Path completo `m/44'/60'/0'/0/{addressIndex}` para un índice ya validado. */
export function derivationPathFor(addressIndex: number): string {
  assertAddressIndexInRange(addressIndex);
  return `${ETHEREUM_BASE_PATH}/${addressIndex}`;
}
40→
/**
 * Valida que `address_index` sea entero en `[0, 2³¹ − 1]` (HU-06-02 RN-9). Un índice
 * `>= 2³¹` produciría silenciosamente una derivación hardened, así que se rechaza con
 * `VALIDATION_ERROR` (HTTP 422) **antes** de intentar derivar.
 */
export function assertAddressIndexInRange(addressIndex: number): void {
  if (
    !Number.isInteger(addressIndex) ||
    addressIndex < 0 ||
50→    addressIndex > MAX_ADDRESS_INDEX
  ) {
    throw validationError(
      [
        {
          field: 'address_index',
          message: `address_index debe ser un entero en el rango [0, ${MAX_ADDRESS_INDEX}] (espacio no-hardened de BIP-32).`,
        },
      ],
      'address_index fuera del rango no-hardened de BIP-44.',
60→    );
  }
}

/**
 * Deriva la cuenta on-chain del `address_index` dado (HU-06-02 RN-1..RN-5).
 *
 * Custodia (RN-6): devuelve únicamente datos **no secretos** (clave pública y dirección);
 * la clave privada nunca se retorna, logea ni serializa desde aquí.
 *
70→ * @throws AppError `VALIDATION_ERROR` si `addressIndex` está fuera de rango (RN-9).
 * @throws InvalidChildKeyError si algún paso produce una clave BIP-32 inválida (RN-8);
 *         usar {@link deriveNextValidAccount} para avanzar automáticamente al siguiente.
 */
export function deriveAccountAt(seed: Uint8Array, addressIndex: number): DerivedAccount {
  const derivationPath = derivationPathFor(addressIndex);
  const node = derivePath(seed, derivationPath);
  const publicKey = publicKeyXY(node.privateKey);
  return {
    addressIndex,
80→    address: publicKeyToAddress(publicKey),
    derivationPath,
    publicKeyXY: publicKey,
  };
}

/**
 * Deriva desde `startIndex` avanzando al índice siguiente cada vez que BIP-32 señaliza una
 * clave hija inválida (`I_L >= n` o `k_hijo == 0`, ~2⁻¹²⁷; HU-06-02 RN-8). Devuelve el
 * índice **efectivamente usado**, que es el que debe registrarse en el mapeo
90→ * cuenta → índice (HU-06-03 RN-1). El comportamiento es determinista y reproducible.
 *
 * @throws AppError `VALIDATION_ERROR` si `startIndex` está fuera de rango (RN-9).
 * @throws AppError `INTERNAL_ERROR` si se agota el espacio no-hardened (HU-06-03 RN-13).
 */
export function deriveNextValidAccount(seed: Uint8Array, startIndex: number): DerivedAccount {
  assertAddressIndexInRange(startIndex);

  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index += 1) {
    try {
100→      return deriveAccountAt(seed, index);
    } catch (error) {
      if (error instanceof InvalidChildKeyError) continue;
      throw error;
    }
  }

  throw new AppError(
    'INTERNAL_ERROR',
    'Espacio de address_index agotado: no hay índices no-hardened disponibles.',
110→  );
}

/**
 * Clave privada derivada del `address_index` dado.
 *
 * **Uso restringido (HU-06-02 RN-6):** material secreto. Existe únicamente para la firma
 * de transacciones de la épica 08 (retiros on-chain), que la consume en memoria. No debe
 * logearse, serializarse ni exponerse por API/WebSocket en ninguna superficie.
 */
120→export function derivePrivateKeyAt(seed: Uint8Array, addressIndex: number): Uint8Array {
  return derivePath(seed, derivationPathFor(addressIndex)).privateKey;
}

