   * Consulta el estado del limitador sin registrar la solicitud actual.
   * Permitir la solicitud número `max`; rechazar a partir de la siguiente dentro de la ventana.
   */
40→  check(key: string, now: number = Date.now()): RateLimitDecision {
    const fresh = this.current(key, now);
    if (fresh.length < this.max) return { allowed: true };
    const oldest = fresh[0] as number;
    const retryAfterMs = Math.max(0, oldest + this.windowMs - now);
    return { allowed: false, retryAfterSeconds: Math.ceil(retryAfterMs / 1000) };
  }

  /** Registra una solicitud contabilizable en la ventana. */
  record(key: string, now: number = Date.now()): void {
50→    const fresh = this.current(key, now);
    fresh.push(now);
    this.hits.set(key, fresh);
  }

  /** Chequea y, si está permitida, contabiliza la solicitud en un solo paso. */
  consume(key: string, now: number = Date.now()): RateLimitDecision {
    const decision = this.check(key, now);
    if (decision.allowed) this.record(key, now);
    return decision;
60→  }

  reset(): void {
    this.hits.clear();
  }
}

