/**
 * Test de aceptación AT-09-02-11 — rate limiting por cuenta y endpoint (HU-09-02 RN-12).
 *
 * Política verificada: sobre los recursos "Auth: Sí" con token válido, 60 requests por
 * ventana deslizante de 60 s, contadas **por cuenta (`accountId`) y por endpoint**. La
 * request 61 responde `RATE_LIMITED` (429) con el envelope uniforme de
 * `00-fundaciones/modelo-de-errores.md` (`details.retryAfterSeconds` entero) y header
 * `Retry-After`.
 *
 * El único endpoint autenticado del alcance de esta etapa es
 * `GET /api/v1/deposit-address?asset=ETH` (ver README, sección 1), así que el escenario se
 * instancia sobre él.
 *
 * Harness dedicado a este archivo: el limitador por cuenta vive en la instancia de la app
 * (`buildApp`), no se reinicia entre tests y agotar la ventana contaminaría a los demás.
 */
import { afterAll, beforeAll, describe, expect, test } from 'vitest';
import {
  bearer,
  get,
  registerAndLogin,
  startHarness,
  type Harness,
} from './helpers/harness.js';
import {
  ACCOUNT_RATE_LIMIT_MAX,
  ACCOUNT_RATE_LIMIT_WINDOW_MS,
} from '../src/config/index.js';
import { SlidingWindowRateLimiter } from '../src/shared/rate-limit.js';
import { ERROR_CATALOG } from '../src/shared/errors.js';

const ENDPOINT = '/api/v1/deposit-address?asset=ETH';

let harness: Harness;
/** Cuenta A: la que agota su ventana. */
let tokenA: string;
/** Cuenta B: control de la separación por cuenta (RN-12). */
let tokenB: string;

beforeAll(async () => {
  harness = startHarness();
  // El registro usa un KDF costoso: se registran sólo las dos cuentas necesarias. Son 4
  // solicitudes a `/auth/*` en total, muy por debajo del límite público por origen (60/60 s).
  ({ token: tokenA } = await registerAndLogin(harness));
  ({ token: tokenB } = await registerAndLogin(harness));
}, 60_000);

afterAll(async () => {
  await harness.destroy();
});

describe('HU-09-02 RN-12 — rate limiting por cuenta y endpoint', () => {
  test(
    'AT-09-02-11: las primeras 60 requests pasan y la 61 responde RATE_LIMITED (429)',
    async () => {
      expect(ACCOUNT_RATE_LIMIT_MAX).toBe(60);
      expect(ACCOUNT_RATE_LIMIT_WINDOW_MS).toBe(60_000);

      // --- 60 requests dentro de la ventana con el mismo token: ninguna limitada.
      for (let i = 1; i <= ACCOUNT_RATE_LIMIT_MAX; i += 1) {
        const response = await get(harness, ENDPOINT, bearer(tokenA));
        expect(
          response.status,
          `la request ${i} no debía ser limitada: ${JSON.stringify(response.body)}`,
        ).toBe(200);
      }

      // --- Request 61: RATE_LIMITED con envelope uniforme.
      const excedida = await get(harness, ENDPOINT, bearer(tokenA));
      expect(excedida.status).toBe(429);
      expect(excedida.status).toBe(ERROR_CATALOG.RATE_LIMITED);
      expect(Object.keys(excedida.body)).toEqual(['error']);
      expect(Object.keys(excedida.body.error).sort()).toEqual(['code', 'details', 'message']);
      expect(excedida.body.error.code).toBe('RATE_LIMITED');
      expect(typeof excedida.body.error.message).toBe('string');
      expect(excedida.body.error.message.length).toBeGreaterThan(0);

      // `details.retryAfterSeconds` entero y acotado por la ventana.
      const retryAfterSeconds = excedida.body.error.details.retryAfterSeconds;
      expect(Number.isInteger(retryAfterSeconds)).toBe(true);
