1→/**
 * Destino de la navegación posterior al login (HU-10-01 RN-3, AT-10-01-01).
 *
 * La **vista de trading** propiamente dicha es HU-10-02 (orderbook y trades en vivo por
 * WebSocket) y está **fuera del alcance de esta corrida**: su backend —épicas 02..05 y los
 * canales WebSocket de HU-09-03/HU-09-04— no está implementado. Esta pantalla es sólo el
 * destino de la ruta, y cumple dos funciones dentro del alcance de HU-10-01:
 *
 *  - hace una **llamada protegida** real (`GET /me`, el único recurso autenticado del
10→ *    contrato disponible hoy) que ejercita RN-7: si responde `UNAUTHENTICATED` (401), la
 *    sesión local se limpia y el usuario vuelve a login con el aviso de sesión expirada;
 *  - muestra la identidad de la cuenta autenticada, **sin** exponer nunca el token (RNE-4).
 */
import { useEffect, useState } from 'react';
import { useSession } from '../session/SessionProvider';
import type { Profile } from '../api/auth';
import { ApiError, MESSAGE_CONNECTION } from '../api/errors';

export function TradingPage(): React.JSX.Element {
20→  const { state, authorizedFetch, signOut } = useSession();
  const initialProfile = state.status === 'authenticated' ? state.profile : null;
  const [profile, setProfile] = useState<Profile | null>(initialProfile);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const result = await authorizedFetch<Profile>('/me');
30→        if (!cancelled) setProfile(result);
      } catch (error) {
        if (cancelled) return;
        // Un `UNAUTHENTICATED` ya limpió la sesión en `authorizedFetch` (RN-7) y la
        // redirección la hace `RequireSession`; acá sólo queda reportar el resto.
        if (error instanceof ApiError && error.code === 'UNAUTHENTICATED') return;
        setLoadError(MESSAGE_CONNECTION);
      }
    })();
    return () => {
40→      cancelled = true;
    };
  }, [authorizedFetch]);

  return (
    <main className="page">
      <header className="topbar">
        <h1>ETH/USDC</h1>
        <div className="topbar__session">
          {profile !== null && <span className="muted">{profile.email}</span>}
50→          <button type="button" onClick={signOut}>
            Salir
          </button>
        </div>
      </header>

      {loadError !== null && (
        <p className="alert alert--error" role="alert">
          {loadError}
        </p>
60→      )}

      <section className="card">
        <h2>Sesión activa</h2>
        {profile === null ? (
          <p role="status">Cargando perfil…</p>
        ) : (
          <dl className="profile">
            <dt>Cuenta</dt>
            <dd>{profile.accountId}</dd>
70→            <dt>Email</dt>
            <dd>{profile.email}</dd>
            <dt>Estado</dt>
            <dd>{profile.status}</dd>
            <dt>Alta</dt>
            <dd>{profile.createdAt}</dd>
          </dl>
        )}
      </section>

80→      <section className="card">
        <h2>Vista de trading</h2>
        <p>
          El orderbook en vivo, el formulario de orden, las órdenes abiertas, el historial, los
          balances y los depósitos/retiros (HU-10-02 a HU-10-06) no forman parte de esta
          corrida: dependen de las épicas 02 a 08 y de los canales WebSocket de la épica 09,
          que todavía no están implementados en el backend.
        </p>
      </section>
    </main>
90→  );
}

