/** Guarda la sesión en el almacén cifrado (RN-2). Nunca lanza. */
export async function saveSession(session: PersistedSession): Promise<void> {
  try {
    await SecureStore.setItemAsync(SESSION_STORAGE_KEY, JSON.stringify(session));
  } catch {
    // El almacén puede rechazar la escritura (dispositivo bloqueado, sin espacio). La sesión
    // sigue viva en memoria; al reabrir la app se pedirán credenciales de nuevo (RN-4).
  }
80→}

/** Borra la sesión del almacén cifrado (RN-5, RN-6). Nunca lanza. */
export async function clearSession(): Promise<void> {
  try {
    await SecureStore.deleteItemAsync(SESSION_STORAGE_KEY);
  } catch {
    // Si no se pudo borrar, el token igualmente queda fuera de memoria; el próximo arranque
    // que logre leerlo recibirá `UNAUTHENTICATED` del backend y volverá a limpiar (RN-5).
  }
90→}

