import { installFetch, networkFailure, type FetchStub } from '../support/fetch-stub';
import { errorResponse, jsonResponse } from '../support/http';
import { visibleText } from '../support/serialize';
import { secureStoreMock } from '../support/secure-store-mock';

/** Almacén en claro que la app **no** debe usar (spy del escenario 8a). */
const mockAsyncStorage = {
  setItem: jest.fn(async () => undefined),
  getItem: jest.fn(async () => null),
  multiSet: jest.fn(async () => undefined),
  removeItem: jest.fn(async () => undefined),
};
jest.mock('@react-native-async-storage/async-storage', () => mockAsyncStorage, { virtual: true });

/** Segundo almacén en claro: el `localStorage` que expone react-native-web. */
const localStorageMock = {
  setItem: jest.fn(),
  getItem: jest.fn(() => null),
  removeItem: jest.fn(),
  clear: jest.fn(),
};

let fetchStub: FetchStub;
let logs: ConsoleSpy;

beforeEach(() => {
  secureStoreMock.reset();
  for (const spy of Object.values(mockAsyncStorage)) spy.mockClear();
  for (const spy of Object.values(localStorageMock)) spy.mockClear();
  Object.defineProperty(globalThis, 'localStorage', {
    value: localStorageMock,
    configurable: true,
    writable: true,
  });
  fetchStub = installFetch();
  fetchStub.respond('/auth/login', jsonResponse(200, LOGIN_OK_BODY));
  fetchStub.respond('/deposit-address', jsonResponse(200, DEPOSIT_ADDRESS_BODY));
  logs = installConsoleSpy();
});

afterEach(() => {
  logs.restore();
});

/** Login completo por la UI hasta la vista autenticada. */
async function loginThroughUi(): Promise<void> {
  render(<App />);
  await waitFor(() => expect(screen.getByTestId('login-submit')).toBeTruthy());
  fireEvent.changeText(screen.getByTestId('login-email'), EMAIL);
  fireEvent.changeText(screen.getByTestId('login-password'), PASSWORD);
  fireEvent.press(screen.getByTestId('login-submit'));
  await waitFor(() => expect(screen.getByTestId('deposit-address')).toBeTruthy());
}

