describe('AT-11-01-08 — el token sólo va al almacenamiento cifrado', () => {
  it('AT-11-01-08: SecureStore.setItemAsync recibe el token y ningún almacén en claro se invoca', async () => {
    await loginThroughUi();

    // El spy del almacén cifrado del SO recibió el token…
    expect(SecureStore.setItemAsync).toBe(secureStoreMock.setItemAsync);
    expect(secureStoreMock.setItemAsync).toHaveBeenCalledTimes(1);
    const [key, value] = secureStoreMock.setItemAsync.mock.calls[0] as [string, string];
    expect(key).toBe(SESSION_STORAGE_KEY);
    expect(value).toContain(TOKEN);

    // …y ningún almacén en claro fue tocado, ni con el token ni con la password.
    for (const [name, spy] of Object.entries(mockAsyncStorage)) {
      expect([name, spy.mock.calls.length]).toEqual([name, 0]);
    }
    for (const [name, spy] of Object.entries(localStorageMock)) {
      expect([name, spy.mock.calls.length]).toEqual([name, 0]);
    }
  });

  it('AT-11-01-08: el único registro persistido es la sesión cifrada, sin la password', async () => {
    await loginThroughUi();

    expect([...secureStoreMock.data.keys()]).toEqual([SESSION_STORAGE_KEY]);
    const stored = secureStoreMock.data.get(SESSION_STORAGE_KEY) ?? '';
    expect(JSON.parse(stored)).toEqual(LOGIN_OK_BODY);
    expect(stored).not.toContain(PASSWORD);
  });

  it('AT-11-01-08: el código de src/ no importa ni usa ningún almacén en claro', () => {
    const offenders: string[] = [];
    for (const file of sourceFiles(join(__dirname, '..', '..', 'src'))) {
      const code = stripComments(readFileSync(file, 'utf8'));
