export function DepositScreen(): React.JSX.Element {
  const { authorizedFetch, signOut } = useSession();

  const [asset, setAsset] = useState<Asset>('ETH');
  const [data, setData] = useState<DepositAddress | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  /**
   * Generación de la consulta en curso. Cambiar de activo (o refrescar) invalida las
   * respuestas anteriores: sin esta guarda, una respuesta lenta de ETH que llegue **después**
   * de la de USDC dejaría en pantalla el QR de un activo y la leyenda de otro, que es
   * exactamente el error que el URI EIP-681 de RN-2 existe para evitar.
   */
  const requestIdRef = useRef(0);

  const load = useCallback(
    async (target: Asset, mode: 'initial' | 'refresh') => {
      const requestId = requestIdRef.current + 1;
      requestIdRef.current = requestId;
      const isCurrent = (): boolean => requestIdRef.current === requestId;

      if (mode === 'refresh') setRefreshing(true);
      else setLoading(true);
      setError(null);
      try {
        const result = await fetchDepositAddress(target, authorizedFetch);
        if (!isCurrent()) return; // respuesta obsoleta: la descarta una consulta posterior
        setData(result);
      } catch (err) {
        if (!isCurrent()) return;
        setData(null);
        if (err instanceof ApiError) {
          // `UNAUTHENTICATED` ya disparó la limpieza de sesión en `authorizedFetch` (RN-11):
          // acá sólo queda no dejar datos en pantalla mientras se vuelve al login.
          setError(messageForCode(err.code));
        } else if (err instanceof TransportError) {
          setError(MESSAGE_CONNECTION);
        } else {
          setError(MESSAGE_CONNECTION);
        }
      } finally {
        if (isCurrent()) {
          setLoading(false);
          setRefreshing(false);
        }
      }
    },
    [authorizedFetch],
  );

  useEffect(() => {
    // Al cambiar de activo se descarta lo mostrado: la dirección es la misma, pero el QR y el
    // contrato del token no, y mostrar los del activo anterior induciría un envío equivocado.
    setCopied(false);
    setData(null);
    void load(asset, 'initial');
  }, [asset, load]);

  const onCopy = useCallback(async () => {
    if (data === null) return;
    // Se copia el **address** (no el URI): es lo que el usuario pega en otra wallet (RN-2).
    await Clipboard.setStringAsync(data.address);
    setCopied(true);
  }, [data]);

  const uri = data === null ? null : safeDepositUri(data);

  return (
    <ScrollView
      contentContainerStyle={styles.container}
      refreshControl={
        <RefreshControl refreshing={refreshing} onRefresh={() => void load(asset, 'refresh')} />
      }
    >
      <View style={styles.header}>
        <Text style={styles.title}>Depositar</Text>

